-- 0085: Günlük oyunların içeriği genişler (yalnız içerik; skorlar, istatistikler ve geçmiş günler aynen kalır).
-- 1) Günün Şehri: her ile 6 ipucu, zordan kolaya; ilk ipucu baştan açık, her yanlış tahminde bir yenisi açılır. Km ve yön aynen.
-- 2) 5 Soruda Bugün: genel soru havuzu 116'dan 492'ye çıkar; aynı soru en erken ~98 gün sonra gelir. İşleyiş aynı.
-- İkisi de yürürlük gününden (yüklemenin ertesi günü) itibaren geçerlidir; önceki günler eski ipucu/soru seçimini korur.

create table oda_icerik_surum (ad text primary key, baslangic date not null);
alter table oda_icerik_surum enable row level security;
revoke all on oda_icerik_surum from anon, authenticated;

-- ---------- Günün Şehri: 6 ipucu ----------
